    ///<summary>Create a new chore. Returns the chore_id of the created chore.</summary>
    ///<param name="configEntryId">Use this if you have more than one ChoreOps setup. It targets one specific setup. eg: abc123def456</param>
    ///<param name="configEntryTitle">Use this if you have more than one ChoreOps setup and they each have unique names. If names repeat, use Config Entry ID. eg: Family Chores</param>
    ///<param name="name">The name of the chore to create. eg: Clean Room</param>
    ///<param name="assignedUserNames">List of assignee names to assign to this chore. eg: [&apos;Emma&apos;, &apos;Jack&apos;]</param>
    ///<param name="points">Points awarded when the chore is completed. eg: 10</param>
    ///<param name="description">Optional description of the chore. eg: Make bed, put toys away, vacuum floor</param>
    ///<param name="icon">Material Design icon for the chore. eg: mdi:broom</param>
    ///<param name="labels">Optional labels to categorize the chore. eg: [&apos;daily&apos;, &apos;bedroom&apos;]</param>
    ///<param name="frequency">How often the chore recurs: none, daily, daily_multi, weekly, biweekly, monthly, quarterly, yearly, custom, custom_from_complete, or period-end (week_end, month_end, quarter_end, year_end). eg: daily</param>
    ///<param name="customInterval">Number of time units between repetitions when frequency is custom or custom_from_complete. eg: 6</param>
    ///<param name="customIntervalUnit">Time unit used with custom_interval when frequency is custom or custom_from_complete. eg: months</param>
    ///<param name="applicableDays">Days of the week when the chore is applicable. eg: [&apos;mon&apos;, &apos;wed&apos;, &apos;fri&apos;]</param>
    ///<param name="completionCriteria">How the chore is completed when multiple assignees are assigned: independent, shared_first, shared_all, rotation_simple, rotation_smart, or rotation_primary_standby. eg: independent</param>
    ///<param name="standbyClaimMode">Controls when standbys can claim this chore (anytime, on_overdue, manual_only). Only applies to Primary &amp; Standby completion criteria. eg: anytime</param>
    ///<param name="approvalResetType">When the chore resets for re-completion. eg: at_midnight_once</param>
    ///<param name="pendingClaims">What to do with pending claims when the approval reset occurs. eg: clear_pending</param>
    ///<param name="overdueHandling">How to handle overdue status. eg: at_due_date</param>
    ///<param name="choreClaimLockUntilWindow">If enabled, assignees cannot claim this chore before the due window begins. eg: False</param>
    ///<param name="autoApprove">Automatically approve the chore when claimed. eg: False</param>
    ///<param name="dueDate">When the chore is due. For INDEPENDENT chores, sets the due date for all assignees assigned to this chore. eg: 2026-01-15T17:00:00</param>
    ///<param name="dueWindowOffset">Duration before due date when chore enters &apos;due&apos; state. Format: &apos;30m&apos;, &apos;1h&apos;, &apos;1d 6h&apos;, etc. Use &apos;0&apos; to disable. eg: 30m</param>
    ///<param name="dueReminderOffset">Duration before due date to send reminder notification. Format: &apos;30m&apos;, &apos;1h&apos;, &apos;1d 6h&apos;, etc. Use &apos;0&apos; to disable. eg: 30m</param>
    public void CreateChore(string name, IEnumerable<string> assignedUserNames, string? configEntryId = null, string? configEntryTitle = null, long? points = null, string? description = null, object? icon = null, IEnumerable<string>? labels = null, object? frequency = null, long? customInterval = null, object? customIntervalUnit = null, IEnumerable<object>? applicableDays = null, object? completionCriteria = null, object? standbyClaimMode = null, object? approvalResetType = null, object? pendingClaims = null, object? overdueHandling = null, bool? choreClaimLockUntilWindow = null, bool? autoApprove = null, DateTime? dueDate = null, string? dueWindowOffset = null, string? dueReminderOffset = null)
    {
        _haContext.CallService("choreops", "create_chore", null, new ChoreopsCreateChoreParameters { ConfigEntryId = configEntryId, ConfigEntryTitle = configEntryTitle, Name = name, AssignedUserNames = assignedUserNames, Points = points, Description = description, Icon = icon, Labels = labels, Frequency = frequency, CustomInterval = customInterval, CustomIntervalUnit = customIntervalUnit, ApplicableDays = applicableDays, CompletionCriteria = completionCriteria, StandbyClaimMode = standbyClaimMode, ApprovalResetType = approvalResetType, PendingClaims = pendingClaims, OverdueHandling = overdueHandling, ChoreClaimLockUntilWindow = choreClaimLockUntilWindow, AutoApprove = autoApprove, DueDate = dueDate, DueWindowOffset = dueWindowOffset, DueReminderOffset = dueReminderOffset });
    }

