    }

    ///<summary>Updates a given target timeframe&apos;s config.</summary>
    ///<param name="targetHours">The optional number of hours the target timeframe sensor should come on during a 24 hour period. eg: 1.5</param>
    ///<param name="targetStartTime">The optional time the evaluation period should start. eg: 06:00</param>
    ///<param name="targetEndTime">The optional time the evaluation period should end. eg: 19:00</param>
    ///<param name="targetOffset">The optional offset to apply to the target timeframe when it starts</param>
    ///<param name="targetMinimumValue">The optional minimum value the selected values should not go below eg: 0.1</param>
    ///<param name="targetMaximumValue">The optional maximum value the selected values should not go above eg: 0.1</param>
    ///<param name="targetWeighting">The optional weighting that should be applied to the selected values eg: 1,2,1</param>
    ///<param name="persistChanges">Determines if the changes should be persisted to the original configuration or should be temporary and reset upon integration reload.</param>
    public void UpdateTargetTimeframeConfig(ServiceTarget target, double? targetHours = null, string? targetStartTime = null, string? targetEndTime = null, string? targetOffset = null, double? targetMinimumValue = null, double? targetMaximumValue = null, string? targetWeighting = null, bool? persistChanges = null)
    {
        _haContext.CallService("target_timeframes", "update_target_timeframe_config", target, new TargetTimeframesUpdateTargetTimeframeConfigParameters { TargetHours = targetHours, TargetStartTime = targetStartTime, TargetEndTime = targetEndTime, TargetOffset = targetOffset, TargetMinimumValue = targetMinimumValue, TargetMaximumValue = targetMaximumValue, TargetWeighting = targetWeighting, PersistChanges = persistChanges });
    }

